(** ** The bound *)

Lemma pow_cases : forall L, (exists ml, 1 <= ml <= 9 /\ L = 2 ^ (ml + 6)) ->
  L = 128 \/ L = 256 \/ L = 512 \/ L = 1024 \/ L = 2048 \/ L = 4096 \/ L = 8192 \/ L = 16384 \/ L = 32768.
Proof.
  intros L [ml [Hml ->]].
  assert (ml = 1 \/ ml = 2 \/ ml = 3 \/ ml = 4 \/ ml = 5 \/ ml = 6 \/ ml = 7 \/ ml = 8 \/ ml = 9) by lia.
  repeat (destruct H as [->|H]; [simpl; tauto|]). subst. simpl. tauto.
Qed.

(** The bound for every memLevel, with the header bound against bit-length codes at overhead 75 at
    lit_bufsize 128 (the only extra fact; block_facts gives it with 100). *)
Theorem overlay_bound_75 : forall L b0 syms ll dl0 lmax dmax H sl sd,
  block_facts L b0 syms ll dl0 lmax dmax H sl sd ->
  (L <= 128 -> forall tau, tau_ok tau -> H <= 71 + charge tau ll (lmax + 1) + charge tau dl0 (dmax + 1) + 75) ->
  forall k, (k <= length syms)%nat -> b0 + 3 + H + cost_sum ll dl0 (firstn k syms) <= 8 * (L + 3 * Z.of_nat k).
Proof.
  intros L b0 syms ll dl0 lmax dmax H sl sd HB H75 k Hk.
  destruct (bf_shift _ _ _ _ _ _ _ _ _ _ HB) as [Hs1 [Hs2 Hs3]].
  assert (Htau100 := bf_tau _ _ _ _ _ _ _ _ _ _ HB).
  destruct (pow_cases L (bf_L _ _ _ _ _ _ _ _ _ _ HB)) as [E|[E|[E|[E|[E|[E|[E|[E|E]]]]]]]]; subst L.
  - apply (cert_bound cert128 cert128_ok 128 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros _ tau Ht. apply H75; auto; lia.
  - apply (cert_bound cert256 cert256_ok 256 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros _ tau Ht. apply Htau100; auto; lia.
  - apply (cert_bound cert512 cert512_ok 512 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert1024 cert1024_ok 1024 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert2048 cert2048_ok 2048 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert4096 cert4096_ok 4096 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert8192 cert8192_ok 8192 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert16384 cert16384_ok 16384 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
  - apply (cert_bound cert32768 cert32768_ok 32768 b0 syms ll dl0 lmax dmax H sl sd HB eq_refl); simpl; try lia.
    intros Hc; exfalso; apply Hc; reflexivity.
Qed.

(** memLevel >= 2: block_facts alone suffices. *)
Theorem overlay_bound_ge256 : forall L b0 syms ll dl0 lmax dmax H sl sd,
  block_facts L b0 syms ll dl0 lmax dmax H sl sd -> 256 <= L ->
  forall k, (k <= length syms)%nat -> b0 + 3 + H + cost_sum ll dl0 (firstn k syms) <= 8 * (L + 3 * Z.of_nat k).
Proof.
  intros L b0 syms ll dl0 lmax dmax H sl sd HB HL. apply (overlay_bound_75 L b0 syms ll dl0 lmax dmax H sl sd HB).
  intros; lia.
Qed.

(** [overlay_bound_statement] with the overhead 75 at lit_bufsize 128. *)
Definition overlay_bound_statement_75 : Prop :=
  forall L b0 syms ll dl0 lmax dmax H sl sd,
    block_facts L b0 syms ll dl0 lmax dmax H sl sd ->
    (L <= 128 -> forall tau, tau_ok tau -> H <= 71 + charge tau ll (lmax + 1) + charge tau dl0 (dmax + 1) + 75) ->
    forall k, (k <= length syms)%nat ->
      b0 + 3 + H + cost_sum ll dl0 (firstn k syms) <= 8 * (L + 3 * Z.of_nat k).

Theorem overlay_bound_75_statement : overlay_bound_statement_75.
Proof. exact overlay_bound_75. Qed.
